P.ui["This zone"] = "Aceasta zona"
P.ui["Tip: /lore journey shows your road so far: the places you've seen, the people you've met and the quests you've done."] = "Sfat: /lore journey iti arata drumul parcurs pana acum: locurile pe care le-ai vazut, persoanele pe care le-ai intalnit si misiunile pe care le-ai indeplinit."
